glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
layout(std140) uniform CCLocal {
  highp mat4 cc_matWorld;
  highp mat4 cc_matWorldIT;
  highp vec4 cc_lightingMapUVParam;
  highp vec4 cc_localShadowBias;
  highp vec4 cc_reflectionProbeData1;
  highp vec4 cc_reflectionProbeData2;
  highp vec4 cc_reflectionProbeBlendData1;
  highp vec4 cc_reflectionProbeBlendData2;
};
in vec3 a_position;
in vec2 a_texCoord;
out vec2 sheet;
out vec2 clearance;
vec4 vert () {
  sheet = a_position.xy;
  clearance = a_texCoord;
  return cc_matViewProj * cc_matWorld * vec4(a_position,1.);
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
uniform sampler2D cardPrint;
layout(std140) uniform InteriorOptics {
  vec4 cavityLamp;
  vec4 cavityView;
  vec4 cavityGold;
};
in vec2 sheet;
in vec2 clearance;
float falloff(vec2 delta) {
  return exp(-dot(delta,delta));
}
float cardDistance(vec2 p, vec2 centre, vec2 halfSize) {
  vec2 d = abs(p-centre)-halfSize+vec2(6.);
  return length(max(d,0.))+min(max(d.x,d.y),0.)-6.;
}
vec3 illuminatedStack(vec2 p) {
  vec2 sight = vec2(.095+.00056*p.x,-.94-.10*cavityView.x);
  vec2 facePt = p + 31.*sight;
  vec2 middlePt = p + 35.*sight;
  vec2 backPt = p + 40.*sight;
  vec2 wallPt = p + 54.*sight;
  vec2 faceToLamp = (facePt-cavityLamp.xy)/cavityLamp.zw;
  vec2 wallToLamp = (wallPt-cavityLamp.xy)/cavityLamp.zw;
  float surfaceLight = exp(-.58*dot(faceToLamp,faceToLamp));
  float wallLight = exp(-.38*dot(wallToLamp,wallToLamp));
  vec3 ember = mix(vec3(.52,.60,.66),vec3(1.,.45,.135),cavityGold.w);
  vec3 lining = cavityGold.rgb;
  vec3 ivory = mix(vec3(.94,.96,1.),vec3(1.,.92,.70),cavityGold.w);
  float gusset = (abs(wallPt.x+.6) - 136.
                 - .30*(wallPt.y-cavityLamp.y) - 2.3*sin(.039*wallPt.y)) / 8.5;
  float fold = exp(-.72*(gusset+.95)*(gusset+.95));
  float returnShadow = exp(-2.1*(gusset-.56)*(gusset-.56));
  float wrinkle = (wallPt.y-cavityLamp.y-22.+.16*(wallPt.x+44.)
                  + 2.8*sin(.034*wallPt.x)) / 8.6;
  float bent = exp(-.91*wrinkle*wrinkle);
  vec3 wall = vec3(.049,.033,.032)+ember*wallLight*(.14+.39*bent);
  wall += lining*wallLight*(.12+.70*fold);
  vec2 sideImage = vec2((abs(wallPt.x+1.)-146.-.23*(wallPt.y-cavityLamp.y))/20.,
                        (wallPt.y-cavityLamp.y-5.)/29.);
  float sideReturn = falloff(sideImage);
  wall += sideReturn*(lining*(.48+.77*fold)+ivory*.28);
  wall *= 1.-.74*returnShadow;
  vec2 centre = vec2(-1.8,cavityLamp.y+27.-215.);
  vec2 size = vec2(140.,215.);
  vec2 frontCard = facePt + vec2(0.,.071*(facePt.x+43.));
  vec2 midCard = middlePt + vec2(1.7,.041*(middlePt.x+43.)-.8);
  vec2 rearCard = backPt + vec2(3.6,.018*(backPt.x+43.)-1.7);
  float front = cardDistance(frontCard,centre,size);
  float mid = cardDistance(midCard,centre,size);
  float rear = cardDistance(rearCard,centre,size);
  wall *= mix(.46,1.,smoothstep(0.,9.,rear));
  vec3 paper = vec3(.068,.047,.042) + lining*(surfaceLight*.27+.14*sideReturn);
  float rearBevel = exp(-1.65*abs(rear+.65));
  float midBevel = exp(-1.45*abs(mid+.70));
  vec3 colour = mix(wall,paper*.66+ivory*surfaceLight*rearBevel*.74,
                    1.-smoothstep(-.42,.42,rear));
  colour = mix(colour,paper+ivory*surfaceLight*midBevel*1.12,
               1.-smoothstep(-.42,.42,mid));
  vec2 uv = clamp((frontCard-centre)/(size*2.)+.5,0.,1.);
  vec3 printInk = mix(vec3(.28,.19,.105),texture(cardPrint,vec2(uv.x,1.-uv.y)).rgb,cavityView.z);
  float printValue = dot(printInk,vec3(.29,.57,.14));
  float foil = smoothstep(.19,.66,printValue);
  #if PARCHMENT_BACK
    vec2 printUV = vec2(uv.x,1.-uv.y);
    vec3 nearby = texture(cardPrint,clamp(printUV+vec2(.0022,-.0016),0.,1.)).rgb;
    float engraved = smoothstep(.026,.18,abs(dot(nearby-printInk,vec3(.30,.59,.11))));
    foil *= mix(.23+.77*engraved,1.,cavityGold.w);
  #endif
  float shoulder = exp(-1.26*abs(front+.90));
  float lampImage = exp(-1.15*dot(faceToLamp,faceToLamp));
  vec3 card = vec3(.052,.032,.026) + printInk*(.34+.65*surfaceLight);
  card += surfaceLight*(ember*.54+lining*(.24+.88*foil));
  card += ivory*lampImage*(.32+1.18*foil+.80*shoulder);
  card += lampImage*lampImage*(lining*.35+ivory*(.16+.66*foil));
  colour = mix(colour,card,1.-smoothstep(-.42,.42,front));
  float gap = clearance.x+clearance.y;
  float lipDepth = min(.24*gap,2.35);
  float bottom = smoothstep(0.,max(.18,lipDepth),clearance.x);
  float top = smoothstep(0.,max(.15,.69*lipDepth),clearance.y);
  float access = .36+.64*bottom*top;
  float crease = .050*sheet.x+.017*sheet.y+.85*sin(.073*sheet.x-.043*sheet.y);
  float curved = .5+.5*cos(crease);
  float facing = curved*curved;
  float spec = facing*facing*facing;
  float relief = .47+.49*facing+.24*foil;
  colour *= mix(.70,relief,smoothstep(2.,19.,gap));
  colour += spec*(.54*wallLight+1.06*lampImage+.34*sideReturn)*lining;
  float exposure = (1.53+.14*surfaceLight)*mix(.63,1.,cavityGold.w);
  return 1.-exp(-exposure*colour*access);
}
vec4 frag () {
  vec2 p = vec2(sheet.x*cavityView.y,sheet.y);
  return vec4(illuminatedStack(p),cavityView.w);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

glsl1.vert:
precision highp float;
uniform highp mat4 cc_matViewProj;
uniform highp mat4 cc_matWorld;
attribute vec3 a_position;
attribute vec2 a_texCoord;
varying vec2 sheet;
varying vec2 clearance;
